def erase_many(root, keys):
    """Delete a sorted nonempty sequence of existing keys by shared paths."""
    def descend(node, lo, hi):
        if lo == hi:
            return node
        # Find the first key not less than the node key in this small batch.
        a, b = lo, hi
        while a < b:
            mid = (a + b) // 2
            if keys[mid] < node.key:
                a = mid + 1
            else:
                b = mid
        cut = a
        left = descend(node.left, lo, cut)
        present = cut < hi and keys[cut] == node.key
        right = descend(node.right, cut + 1 if present else cut, hi)
        if not present:
            return _join(node.key, node.value, left, right)
        if left is None:
            return right
        if right is None:
            return left
        successor, right = pop_min(right)
        return _join(successor.key, successor.value, left, right)
    return descend(root, 0, len(keys))


def rank_remove_many(root, ranks):
    """Remove sorted resident ranks (duplicates allowed) in one tree walk."""
    def descend(node, lo, hi):
        if lo == hi:
            return node
        a, b = lo, hi
        while a < b:
            mid = (a + b) // 2
            if ranks[mid] < node.key:
                a = mid + 1
            else:
                b = mid
        cut = a
        end = cut
        while end < hi and ranks[end] == node.key:
            end += 1
        left = descend(node.left, lo, cut)
        right = descend(node.right, end, hi)
        # Rank entries are retained even at zero population, so no rotations.
        return RankNode(node.key, node.live - (end - cut), node.served, left, right)
    return descend(root, 0, len(ranks))
